html.script:
odoo.define('auction.auction_player', function (require) {
    'use strict';

    var core = require('web.core');
    var Dialog = require('web.Dialog');

    var _t = core._t;

    function redirectToURL(url) {
        window.location.href = url;
    }

    var AuctionPlayer = {
        showModal: function (ev) {
            ev.preventDefault();
            var self = this;
            Dialog.confirm(this, _t("Are you sure you want to mark this player as SOLD?"), {
                confirm_callback: function () {
                    // Code to mark the player as SOLD
                    // You can call a controller method here to handle this action
                },
            });
        },
    };

    core.action_registry.add('auction_player', AuctionPlayer);
});

body.script:
(function(){
  let lastPlayerId = null;
  let lastState    = null;
  let lastMysteryRevealed = null;
  var _teamsData   = [];
  var _sport = (document.documentElement.getAttribute('data-sport') || 'cricket').toLowerCase();

  function cricketRoleTags(role) {
    var lo = (role || '').toLowerCase().replace(/[-_\s]+/g, '');
    if (!lo) return '';
    var isWK = lo.indexOf('wicket') >= 0 || lo === 'wk' || lo.indexOf('keeper') >= 0;
    var isAR = lo.indexOf('allround') >= 0;
    var isBat = lo.indexOf('bat') >= 0;
    var isBowl = lo.indexOf('bowl') >= 0;
    var tags = [];
    if (isAR || (isBat && isBowl)) {
      tags.push('<span class="lb-role-tag bat">BAT</span>');
      tags.push('<span class="lb-role-tag bowl">BOWL</span>');
    } else if (isWK && isBat) {
      tags.push('<span class="lb-role-tag wk">WK</span>');
      tags.push('<span class="lb-role-tag bat">BAT</span>');
    } else if (isWK) {
      tags.push('<span class="lb-role-tag wk">WK</span>');
    } else if (isBat) {
      tags.push('<span class="lb-role-tag bat">BAT</span>');
    } else if (isBowl) {
      tags.push('<span class="lb-role-tag bowl">BOWL</span>');
    }
    if (!tags.length) return '';
    return '<span class="lb-role-tags">' + tags.join('') + '</span>';
  }

  function footballPosBadge(p) {
    var code = (p.position_code || '').trim().toUpperCase();
    var name = (p.position_name || '').trim();
    if (!code && name) {
      code = name.replace(/[-_/]+/g, ' ').split(/\s+/).map(function(w) {
        return w.charAt(0);
      }).join('').toUpperCase().slice(0, 3);
    }
    if (!code) return '';
    var title = name || code;
    return '<span class="lb-pos-badge" title="' + lbEsc(title) + '">' + lbEsc(code) + '</span>';
  }

  function playerRoleMetaHtml(p) {
    if (_sport === 'football') {
      return footballPosBadge(p) || (p.role ? '<span class="lb-pos-badge">' + lbEsc(p.role) + '</span>' : '');
    }
    var tags = cricketRoleTags(p.role);
    if (tags) return tags;
    return p.role ? lbEsc(p.role) : '';
  }


  // ── IPL layout helpers ────────────────────────────────────────
  function fmtParts(n) {
    var sym = (window.pointUnitSymbol && window.pointUnitSymbol()) || 'pts';
    return { num: Number(n || 0).toLocaleString('en-US'), sym: String(sym).toUpperCase() };
  }
  function lbxSet(el, html) {
    if (!el || el._lbxH === html) return;
    el._lbxH = html;
    el.innerHTML = html;
  }
  function lbxFitAmount() {
    var el = document.querySelector('.lbx-bid-amt');
    if (!el) return;
    el.style.fontSize = '';
    var cw = el.clientWidth, sw = el.scrollWidth;
    if (cw && sw > cw) {
      var fs = parseFloat(getComputedStyle(el).fontSize) || 0;
      if (fs) el.style.fontSize = Math.floor(fs * cw / sw * 0.97) + 'px';
    }
  }
  window.addEventListener('resize', lbxFitAmount);

  // Sponsors scroll right-to-left only when they overflow the strip
  function lbxFitSponsors() {
    var view = document.getElementById('lbx-spon-view');
    var track = document.getElementById('lb-sponsor-track');
    if (!view || !track) return;
    if (track.getAttribute('data-dup') === '1') return;
    view.classList.remove('is-scroll'); track.classList.remove('is-scroll');
    if (track.scrollWidth > view.clientWidth + 2 && track.children.length) {
      track.innerHTML += track.innerHTML;
      track.setAttribute('data-dup', '1');
      view.classList.add('is-scroll'); track.classList.add('is-scroll');
    }
  }
  window.addEventListener('load', lbxFitSponsors);

  // Updates ticker: latest sales first, then the standing messages
  var _lbxTickerBase = null;
  function lbxBuildTicker(history) {
    var track = document.getElementById('lbx-ticker-track');
    if (!track) return;
    if (!_lbxTickerBase) {
      var tn = (document.getElementById('hdr-t-name') || {}).textContent || 'Live Auction Board';
      _lbxTickerBase = [tn.trim(), 'Live auction in progress', 'Bids update in real time',
        'Next player announced automatically', 'Powered by AuctionChamp'];
    }
    var items = [];
    (history || []).slice(0, 6).forEach(function(h) {
      if (h && h.message) items.push(String(h.message).replace(/\s+/g, ' '));
    });
    items = items.concat(_lbxTickerBase);
    var html = items.map(function(t) { return '<span class="lbx-ticker-item">' + lbEsc(t) + '</span>'; }).join('');
    track.innerHTML = html + html;
    track.style.animationDuration = Math.max(30, Math.round(track.scrollWidth / 2 / 70)) + 's';
  }

  // Highlight the leading / winning team in the teams strip
  var _lbxLead = null;
  function lbxMarkLeadTeam(name, sold) {
    _lbxLead = name ? { name: String(name).trim().toLowerCase(), sold: !!sold } : null;
    var chips = document.querySelectorAll('#lb-teams-grid .lbx-team');
    for (var i = 0; i < chips.length; i++) {
      var hit = _lbxLead && (chips[i].getAttribute('data-name') || '') === _lbxLead.name;
      chips[i].classList.toggle('is-lead', !!hit);
      chips[i].classList.toggle('is-sold', !!(hit && _lbxLead.sold));
    }
  }

  // Player name: first name white, surname gold (two lines)
  function lbxNameHtml(name) {
    var words = String(name || '—').trim().split(/\s+/);
    if (words.length < 2) return lbEsc(words[0] || '—');
    return lbEsc(words.slice(0, -1).join(' ')) + '<span class="lbx-pn-last">' + lbEsc(words[words.length - 1]) + '</span>';
  }

  // Long names: shrink until the identity block fits
  function lbxFitName() {
    var el = document.getElementById('lb-pname');
    var mid = document.querySelector('.lbx-mid');
    if (!el || !mid) return;
    el.style.fontSize = '';
    var n = 0;
    while (n++ < 16 && (mid.scrollHeight > mid.clientHeight + 1 || el.scrollWidth > el.clientWidth + 1)) {
      var fs = parseFloat(getComputedStyle(el).fontSize) || 0;
      if (fs <= 20) break;
      el.style.fontSize = (fs * 0.92) + 'px';
    }
  }
  window.addEventListener('resize', lbxFitName);
  if (document.fonts && document.fonts.ready) document.fonts.ready.then(lbxFitName);
  if (window.MutationObserver) {
    var _fitMo = new MutationObserver(lbxFitName);
    ['lb-pname', 'lb-badges-row'].forEach(function(id) {
      var n = document.getElementById(id);
      if (n) _fitMo.observe(n, { childList: true, subtree: true, characterData: true });
    });
    ['lb-stats-row', 'lb-base-row'].forEach(function(id) {
      var n = document.getElementById(id);
      if (n) _fitMo.observe(n, { childList: true, subtree: true, attributes: true, attributeFilter: ['style'] });
    });
  }

  // Phone tab switch
  document.addEventListener('click', function(e) {
    var b = e.target && e.target.closest ? e.target.closest('#lbx-tabs button') : null;
    if (!b) return;
    var main = document.getElementById('lb-main');
    if (main) main.setAttribute('data-tab', b.getAttribute('data-tab'));
    var all = document.querySelectorAll('#lbx-tabs button');
    for (var i = 0; i < all.length; i++) all[i].classList.toggle('on', all[i] === b);
  });

  // ── Break time + advertiser state ─────────────────────────────
  var _breakActive   = false;
  var _breakStartTs  = null;
  var _breakClockId  = null;
  var _adList        = [];
  var _adSig         = '';

  function startBreakClock() {
    if (_breakClockId) return;
    _breakClockId = setInterval(function() {
      if (!_breakStartTs) return;
      var e = Math.floor((Date.now() - _breakStartTs) / 1000);
      var m = Math.floor(e / 60), s = e % 60;
      var el = document.getElementById('lb-brk-timer');
      if (el) el.textContent = '\u25cf Break in progress \u2014 ' + (m > 0 ? m + 'm ' : '') + String(s).padStart(2,'0') + 's';
    }, 1000);
  }
  function stopBreakClock() {
    if (_breakClockId) { clearInterval(_breakClockId); _breakClockId = null; }
  }

  function adsSignature(ads) {
    return (ads || []).map(function(a) {
      return String(a.id || '') + '|' + String(a.image_url || '') + '|' + String(a.name || '');
    }).join('||');
  }

  function lbxAdCardHtml(ad) {
    var inner = ad.image_url
      ? '<img src="' + lbEsc(ad.image_url) + '" alt="' + lbEsc(ad.name || '') + '" title="' + lbEsc(ad.name || '') + '" onerror="this.style.display=\'none\'">'
      : '<span>' + lbEsc(ad.name || '') + '</span>';
    return '<div class="lbx-spon-card">' + inner + '</div>';
  }

  function updateAds(ads) {
    var next = ads || [];
    var sig = adsSignature(next);
    var changed = sig !== _adSig;
    _adList = next;
    _adSig = sig;
    var hasAds = _adList.length > 0;

    if (changed) {
      var cards = _adList.map(lbxAdCardHtml).join('');
      // Break screen: sponsor logos scroll right to left (CSS transform only)
      var brkAds = document.getElementById('lb-brk-ads');
      var brkTrack = document.getElementById('lb-brk-ads-track');
      if (brkTrack) {
        var half = new Array(Math.max(1, Math.ceil(8 / Math.max(1, _adList.length))) + 1).join(cards);
        brkTrack.innerHTML = hasAds ? half + half : '';
      }
      if (brkAds) brkAds.style.display = hasAds ? '' : 'none';
      // Footer sponsor strip
      var stripTrack = document.getElementById('lb-sponsor-track');
      if (stripTrack && hasAds) {
        stripTrack.removeAttribute('data-dup');
        stripTrack.innerHTML = cards;
        lbxFitSponsors();
      }
    }
    var strip = document.getElementById('lb-sponsor-strip');
    if (strip) strip.style.display = hasAds ? '' : 'none';
    document.body.classList.toggle('lb-has-sponsors', hasAds);
  }

  var _lbTyConfettiBuilt = false;
  var _lbTyPhase = '';
  var _lbWaitPhase = {};
  function idleHeadline(wp) {
    wp = wp || _lbWaitPhase || {};
    if (wp.idle_headline) return wp.idle_headline;
    if (wp.phase === 'loading_unsold') return 'Loading from Unsold';
    if (wp.phase === 'draft_soon') return 'Players will enter the auction soon';
    if (wp.phase === 'about_to_begin') return 'The battle for talent begins soon';
    if (wp.phase === 'completed') return 'Thank You Viewers';
    return 'Waiting for next player';
  }
  function idleShowDots(wp) {
    return ((wp || _lbWaitPhase || {}).phase !== 'completed');
  }
  function idleDotsHtml() {
    return '<span class="lb-dots" aria-hidden="true"><span>.</span><span>.</span><span>.</span><span>.</span></span>';
  }
  function idleLineHtml(text, withDots) {
    var html = '<span class="lb-idle-copy">' + lbEsc(text || '') + '</span>';
    return withDots ? html + idleDotsHtml() : html;
  }
  function rememberWaitPhase(wp) {
    if (wp) _lbWaitPhase = wp;
    return _lbWaitPhase;
  }
  function buildLbTyConfetti() {
    var box = document.getElementById('lbTyConfetti');
    if (!box || _lbTyConfettiBuilt) return;
    var colors = ['#FFD700', '#FF6B6B', '#4CAF50', '#00BCD4', '#FF9800', '#E040FB', '#42A5F5', '#66BB6A'];
    var html = '';
    for (var i = 0; i < 28; i++) {
      var left = Math.round(Math.random() * 100);
      var delay = (Math.random() * 4).toFixed(2);
      var dur = (3.5 + Math.random() * 3.5).toFixed(2);
      var dx = Math.round(-40 + Math.random() * 80);
      var color = colors[i % colors.length];
      html += '<span class="lb-ty-piece" style="left:' + left + '%;background:' + color +
        ';animation-delay:' + delay + 's;animation-duration:' + dur + 's;--dx:' + dx + 'px"></span>';
    }
    box.innerHTML = html;
    _lbTyConfettiBuilt = true;
  }
  function replayLbTyCeremony() {
    var overlay = document.getElementById('lb-thankyou-overlay');
    if (!overlay) return;
    overlay.classList.add('lb-ty-replay');
    void overlay.offsetWidth;
    overlay.classList.remove('lb-ty-replay');
  }
  function handleThankYou(waitPhase, tournamentData, player) {
    waitPhase = waitPhase || {};
    var phase = waitPhase.phase || '';
    if (player && phase === 'completed') {
      phase = 'waiting';
    }
    var overlay = document.getElementById('lb-thankyou-overlay');
    var liveBadge = document.querySelector('.lbx-live');
    var entering = phase === 'completed' && _lbTyPhase !== 'completed';

    if (!overlay) {
      _lbTyPhase = phase;
      return;
    }

    if (phase === 'completed') {
      document.body.classList.add('lb-thankyou-active');
      overlay.classList.add('active');
      overlay.setAttribute('aria-hidden', 'false');

      var titleEl = document.getElementById('lbTyThanksText');
      var shimmerEl = document.getElementById('lbTyThanksShimmer');
      var title = waitPhase.thanks_title || 'Thank You Viewers';
      if (titleEl) titleEl.textContent = title;
      if (shimmerEl) shimmerEl.textContent = title;

      var msgEl = document.getElementById('lbTyMessage');
      if (msgEl) {
        msgEl.textContent = waitPhase.message ||
          'THANKS FOR STAYING TUNED TO THE AUCTION. THE ROAD TO GLORY BEGINS.';
      }
      var tourEl = document.getElementById('lbTyTourName');
      if (tourEl) tourEl.textContent = waitPhase.tournament_name || (tournamentData && tournamentData.name) || '';

      var logoWrap = document.getElementById('lbTyLogoWrap');
      var logoImg = document.getElementById('lbTyLogo');
      var logoUrl = (tournamentData && tournamentData.logo_url) || '';
      if (logoWrap && logoImg) {
        if (logoUrl) {
          logoImg.src = logoUrl;
          logoWrap.classList.add('is-on');
        } else {
          logoWrap.classList.remove('is-on');
        }
      }

      if (liveBadge) liveBadge.innerHTML = '<span class="lbx-live-dot"></span> COMPLETE';

      buildLbTyConfetti();
      if (entering) replayLbTyCeremony();
    } else {
      document.body.classList.remove('lb-thankyou-active');
      overlay.classList.remove('active');
      overlay.setAttribute('aria-hidden', 'true');
      if (liveBadge && _lbTyPhase === 'completed') {
        liveBadge.innerHTML = '<span class="lbx-live-dot"></span> LIVE';
      }
    }
    _lbTyPhase = phase;
  }

  function handleBreakTime(isBreak, tournamentData) {
    var overlay = document.getElementById('lb-break-overlay');
    if (document.body.classList.contains('lb-thankyou-active')) {
      // Thank You ceremony takes priority over break overlay
      if (overlay) overlay.classList.remove('active');
      return;
    }
    if (isBreak) {
      if (!_breakActive) {
        _breakActive  = true;
        _breakStartTs = Date.now();
        // Set tournament logo once
        var logoEl = document.getElementById('lb-brk-logo');
        if (logoEl && tournamentData && tournamentData.logo_url && !logoEl.dataset.set) {
          logoEl.innerHTML = '<img src="' + tournamentData.logo_url + '" alt="" onerror="this.innerHTML=\'<span class=lb-brk-logo-ph>&#127942;</span>\'">';
          logoEl.dataset.set = '1';
        }
        var brkName = document.getElementById('lbx-brk-name');
        if (brkName && tournamentData && tournamentData.name) brkName.textContent = tournamentData.name;
        overlay.classList.add('active');
        startBreakClock();
      }
    } else {
      if (_breakActive) {
        _breakActive  = false;
        _breakStartTs = null;
        overlay.classList.remove('active');
        stopBreakClock();
        var timerEl = document.getElementById('lb-brk-timer');
        if (timerEl) timerEl.textContent = '\u25cf Break in progress';
      }
    }
  }

  function fmtPts(n) {
    var sym = (window.pointUnitSymbol && window.pointUnitSymbol()) || 'pts';
    var pos = (window.AuctionPointUnit && window.AuctionPointUnit.cfg().position) || 'after';
    var space = !(window.AuctionPointUnit && window.AuctionPointUnit.cfg().with_space === false);
    var sep = space ? ' ' : '';
    function wrap(core) {
      return pos === 'before' ? (sym + sep + core) : (core + sep + sym);
    }
    if (!n) return wrap('0');
    if (n >= 100000) return wrap((n/100000).toFixed(2).replace(/\.?0+$/,'') + 'L');
    if (n >= 1000)   return wrap((n/1000).toFixed(1).replace(/\.?0+$/,'') + 'K');
    return wrap(String(n));
  }

  function lbEsc(s) {
    return String(s == null ? '' : s)
      .replace(/&/g, '&amp;').replace(/</g, '&lt;')
      .replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  }

  function lbStat(label, val) {
    return '<div class="lb-stat-chip"><div class="lb-stat-lbl">' + lbEsc(label) +
           '</div><div class="lb-stat-val">' + lbEsc(val) + '</div></div>';
  }

  function lbExtraAttrs(p) {
    const extras = (p && (p.extra_attributes || p.other_attributes)) || [];
    let html = '';
    for (let i = 0; i < extras.length && i < 3; i++) {
      const oa = extras[i];
      if (oa && oa.label) html += lbStat(oa.label, oa.value || '—');
    }
    return html;
  }

  function lbChips(items) {
    if (!items || !items.length) return '';
    let html = '';
    for (let i = 0; i < items.length; i++) {
      const it = items[i] || {};
      const ic = it.icon ? (lbEsc(it.icon) + ' ') : '';
      html += '<span class="lb-tag-chip">' + ic + lbEsc(it.name || '') + '</span>';
    }
    return html;
  }

  function safeImg(url) {
    return url || '';
  }

  // ── Clock ──────────────────────────────────────────────────────
  function updateClock() {
    const now = new Date();
    document.getElementById('lb-clock').textContent =
      now.toLocaleTimeString('en-IN', {hour:'2-digit', minute:'2-digit', second:'2-digit'});
  }
  var _clockTimer = setInterval(updateClock, 1000);
  updateClock();
  window.addEventListener('beforeunload', function() { clearInterval(_clockTimer); });

  // ── Player photo (off-DOM preload so display:none cannot cancel onload) ─
  var _lbPhotoLoadToken = 0;
  var _lbLastPhotoUrl = null;
  var _lbLastPhotoPlayerId = null;
  var _lbPhotoProbe = null;
  var _lbPhotoTimer = null;
  var _fpHistory = null;
  var _fpMvp = null;
  var _fpTeams = null;

  function lbShowPhotoLoader() {
    var ph = document.getElementById('lb-photo-ph');
    if (!ph) return;
    ph.classList.add('lb-photo-loading');
    ph.style.display = 'flex';
    ph.innerHTML = ''
      + '<div class="lb-photo-loader" aria-hidden="true">'
      +   '<span class="lb-photo-loader-ring lb-photo-loader-ring--outer"></span>'
      +   '<span class="lb-photo-loader-ring"></span>'
      +   '<span class="lb-photo-loader-core"></span>'
      + '</div>'
      + '<div class="lb-photo-loading-copy">'
      +   '<span class="lb-photo-loading-txt">Loading player photo</span>'
      +   '<span class="lb-photo-loading-dots"><span></span><span></span><span></span></span>'
      + '</div>';
  }

  function lbPhotoFallbackUrl(url) {
    return String(url || '')
      .replace(/([?&])sz=pj(&|$)/, function (_, q, end) { return end === '&' ? q : ''; })
      .replace(/[?&]$/, '');
  }

  function lbClearPhotoProbe() {
    if (_lbPhotoTimer) { clearTimeout(_lbPhotoTimer); _lbPhotoTimer = null; }
    if (_lbPhotoProbe) {
      _lbPhotoProbe.onload = null;
      _lbPhotoProbe.onerror = null;
      _lbPhotoProbe = null;
    }
  }

  function lbApplyPlayerPhoto(p) {
    var img = document.getElementById('lb-player-img');
    var ph = document.getElementById('lb-photo-ph');
    if (!img || !ph) return;
    var mysteryHidden = !!(p && (p.is_mystery || p.is_mystery) && !(p.mystery_revealed || p.mystery_revealed));

    function showPlaceholder() {
      img.onload = null;
      img.onerror = null;
      img.style.display = 'none';
      img.style.opacity = '0';
      img.style.filter = '';
      img.removeAttribute('src');
      ph.classList.remove('lb-photo-loading');
      ph.style.display = 'flex';
      ph.textContent = mysteryHidden ? '?' : '👤';
    }

    function showPhoto(src) {
      img.onload = null;
      img.onerror = null;
      if (src && img.getAttribute('src') !== src) {
        img.src = src;
      }
      img.style.filter = mysteryHidden ? 'grayscale(1) brightness(0.72)' : '';
      img.style.display = 'block';
      img.style.opacity = '1';
      ph.classList.remove('lb-photo-loading');
      ph.style.display = 'none';
    }

    if (!p || !p.photo_url) {
      _lbPhotoLoadToken += 1;
      _lbLastPhotoUrl = null;
      _lbLastPhotoPlayerId = null;
      lbClearPhotoProbe();
      showPlaceholder();
      return;
    }

    var url = p.photo_url;
    var pid = p.id != null ? Number(p.id) : 0;
    var showing = img.style.display !== 'none' && img.complete && img.naturalWidth;

    // Same player: leave the in-flight preload (or the visible photo) alone.
    if (pid && _lbLastPhotoPlayerId === pid) {
      _lbLastPhotoUrl = url;
      if (showing) showPhoto(img.getAttribute('src') || url);
      return;
    }

    var token = ++_lbPhotoLoadToken;
    _lbLastPhotoUrl = url;
    _lbLastPhotoPlayerId = pid || null;
    lbClearPhotoProbe();
    img.style.filter = mysteryHidden ? 'grayscale(1) brightness(0.72)' : '';
    img.style.display = 'none';
    img.style.opacity = '0';
    lbShowPhotoLoader();

    function arm(src, triedFallback) {
      if (token !== _lbPhotoLoadToken) return;
      var probe = new Image();
      _lbPhotoProbe = probe;
      probe.onload = function () {
        if (token !== _lbPhotoLoadToken) return;
        lbClearPhotoProbe();
        showPhoto(src);
      };
      probe.onerror = function () {
        if (token !== _lbPhotoLoadToken) return;
        var fb = lbPhotoFallbackUrl(src);
        if (!triedFallback && fb && fb !== src) {
          arm(fb, true);
          return;
        }
        _lbLastPhotoUrl = null;
        _lbLastPhotoPlayerId = null;
        lbClearPhotoProbe();
        showPlaceholder();
      };
      probe.src = src;
      if (probe.complete && probe.naturalWidth) {
        probe.onload();
      }
    }

    arm(url, false);
    _lbPhotoTimer = setTimeout(function () {
      if (token !== _lbPhotoLoadToken) return;
      var fb = lbPhotoFallbackUrl(url);
      if (fb && fb !== url) arm(fb, true);
    }, 4000);
  }

  // ── Projector-style SOLD / UNSOLD seal on the live-board photo ──
  function setLbSealArcText(textId, value) {
    var el = document.getElementById(textId);
    if (!el) return;
    var path = el.querySelector('textPath');
    if (path) path.textContent = value || '';
  }
  function hideLbPhotoStatus() {
    var overlay = document.getElementById('lbPhotoStatus');
    if (overlay) overlay.classList.remove('lb-status-show');
    var rb = document.getElementById('lbxRibbon');
    if (rb) rb.classList.remove('is-on');
  }
  function showLbxRibbon(kind) {
    var rb = document.getElementById('lbxRibbon');
    if (!rb) return;
    if (rb.classList.contains('is-on') && rb.getAttribute('data-kind') === kind) return;
    rb.setAttribute('data-kind', kind);
    rb.textContent = kind === 'sold' ? 'SOLD' : 'UNSOLD';
    rb.classList.remove('is-on');
    void rb.offsetWidth;
    rb.classList.add('is-on');
  }
  function showLbPhotoStatus(kind, soldInfo) {
    var overlay = document.getElementById('lbPhotoStatus');
    if (!overlay) return;
    var isSold = kind === 'sold';
    overlay.setAttribute('data-kind', isSold ? 'sold' : 'unsold');
    setLbSealArcText('lbSealArcTopText', isSold ? 'SOLD TO' : 'NO BID');
    var teamName = ((soldInfo && soldInfo.team_name) || (isSold ? 'TEAM' : 'UNSOLD')).toUpperCase();
    setLbSealArcText('lbSealArcBotText', teamName);
    var logoEl = document.getElementById('lbStatusSealLogo');
    if (logoEl) {
      if (isSold && soldInfo && soldInfo.team_logo_url) {
        logoEl.src = soldInfo.team_logo_url;
        logoEl.classList.add('is-on');
      } else {
        logoEl.removeAttribute('src');
        logoEl.classList.remove('is-on');
      }
    }
    overlay.classList.remove('lb-status-show');
    void overlay.offsetWidth;
    overlay.classList.add('lb-status-show');
  }

  // ── Render Player Panel ────────────────────────────────────────
  function renderPlayer(p, soldInfo, waitPhase) {
    rememberWaitPhase(waitPhase);
    var pnameEl = document.getElementById('lb-pname');
    if (!p) {
      lbxSet(pnameEl, idleLineHtml(idleHeadline(_lbWaitPhase), idleShowDots(_lbWaitPhase)));
      pnameEl.classList.add('lb-idle-wait');
      document.getElementById('lb-psub').textContent = '';
      var kIdle = document.getElementById('lb-kicker'); if (kIdle) kIdle.textContent = '';
      lbApplyPlayerPhoto(null);
      document.getElementById('lb-sl-overlay').style.display = 'none';
      document.getElementById('lb-state-overlay').style.display = 'none';
      hideLbPhotoStatus();
      var lockClear = document.getElementById('lb-mystery-lock');
      if (lockClear) lockClear.style.display = 'none';
      lbxSet(document.getElementById('lb-badges-row'), '');
      document.getElementById('lb-stats-row').style.display = 'none';
      document.getElementById('lb-base-row').style.display = 'none';
      return;
    }

    pnameEl.classList.remove('lb-idle-wait');

    // Photo — preload before reveal so previous sold player never stays up
    lbApplyPlayerPhoto(p);

    const mysteryHidden = !!(p.is_mystery && !p.mystery_revealed);
    const mysteryLock = document.getElementById('lb-mystery-lock');

    // Name + sub — Mystery Player? only; no role ??? / small ?
    lbxSet(pnameEl, lbxNameHtml(mysteryHidden ? 'Mystery Player?' : (p.name || '—')));
    var kEl = document.getElementById('lb-kicker');
    if (kEl) kEl.textContent = (p.state === 'sold' || p.state === 'unsold') ? 'Auction Result' : 'Now Auctioning';
    const subRole = (p.tournament_type === 'football')
      ? (p.dominant_position || p.role || '')
      : (p.tournament_type === 'kabaddi'
          ? (p.kabaddi_role || p.role || '')
          : (p.tournament_type === 'badminton'
              ? (p.badminton_category || p.role || '')
              : (p.role || '')));
    document.getElementById('lb-psub').textContent  =
      mysteryHidden ? '' : [subRole, p.tier_name].filter(Boolean).join(' · ');

    // SL badge — hidden for unrevealed mystery players
    const slEl = document.getElementById('lb-sl-overlay');
    if (p.sl_no && !mysteryHidden) { slEl.style.display = ''; document.getElementById('lb-sl-num').textContent = p.sl_no; }
    else           { slEl.style.display = 'none'; }

    // State overlay
    const stEl = document.getElementById('lb-state-overlay');
    stEl.style.display = '';
    stEl.className = 'lb-state-overlay lb-state-' + (p.state || 'auction');
    stEl.textContent = p.state === 'sold' ? 'SOLD' : p.state === 'unsold' ? 'UNSOLD' : '\u25cf LIVE NOW';

    // Projector-style SOLD / UNSOLD seal on the player photo
    if (p.state === 'sold' && soldInfo) {
      showLbPhotoStatus('sold', soldInfo);
      stEl.style.display = 'none';
    } else if (p.state === 'unsold') {
      showLbPhotoStatus('unsold', null);
      stEl.style.display = 'none';
    } else {
      hideLbPhotoStatus();
    }
    if (mysteryLock) mysteryLock.style.display = mysteryHidden ? 'flex' : 'none';

    // Badges
    const isFootball = (p.tournament_type === 'football');
    const isBadminton = (p.tournament_type === 'badminton');
    const isKabaddi = (p.tournament_type === 'kabaddi');
    let badgesHtml = '';
    if (p.tier_name && !mysteryHidden) {
      badgesHtml += `<span class="lb-badge lb-b-tier" style="background:${p.tier_color || '#2252b5'}">${p.tier_name}</span>`;
    }
    if (!mysteryHidden) {
      if (isFootball) {
        if (p.dominant_position) {
          badgesHtml += `<span class="lb-badge lb-b-role">${lbEsc(p.dominant_position)}</span>`;
        }
      } else if (isBadminton) {
        const cat = p.badminton_category || p.role;
        if (cat) badgesHtml += `<span class="lb-badge lb-b-role">${lbEsc(cat)}</span>`;
      } else if (isKabaddi) {
        const kbRole = p.kabaddi_role || p.role;
        if (kbRole) badgesHtml += `<span class="lb-badge lb-b-role">${lbEsc(kbRole)}</span>`;
      } else if (p.role) {
        badgesHtml += `<span class="lb-badge lb-b-role">${p.role}</span>`;
      }
    }
    if (p.icon_player && !mysteryHidden) {
      badgesHtml += `<span class="lb-badge lb-b-icon">⭐ Icon</span>`;
    }
    lbxSet(document.getElementById('lb-badges-row'), badgesHtml);

    // Stats row — hide identity attributes while mystery is locked
    const statsRow = document.getElementById('lb-stats-row');
    if (mysteryHidden) {
      statsRow.style.display = 'none';
      lbxSet(statsRow, '');
    } else if (isFootball) {
      let r1 = '';
      if (p.preferred_foot) r1 += lbStat('Foot', p.preferred_foot);
      if (p.age) r1 += lbStat('Age', String(p.age));
      if (p.secondary_positions && p.secondary_positions.length)
        r1 += lbStat('Secondary', p.secondary_positions.join(', '));
      r1 += lbExtraAttrs(p);
      let r2 = '';
      if (p.blood_group) r2 += lbStat('Blood', p.blood_group);
      let sh = r1;
      if (r1 && r2) sh += '<div class="lb-stat-break"></div>';
      sh += r2;
      const fChips = lbChips(p.playing_styles) + lbChips(p.strengths);
      if (fChips) sh += (sh ? '<div class="lb-stat-break"></div>' : '') + fChips;
      if (sh) {
        statsRow.style.display = 'flex';
        lbxSet(statsRow, sh);
      } else {
        statsRow.style.display = 'none';
      }
    } else if (isBadminton) {
      let r1 = '';
      r1 += lbStat('Age', p.age ? String(p.age) : '—');
      r1 += lbStat('Category', p.badminton_category || p.role || '—');
      r1 += lbStat('Hand', p.preferred_hand || p.preferred_foot || '—');
      r1 += lbStat('Style', p.badminton_style || '—');
      r1 += lbStat('Level', p.skill_level || '—');
      r1 += lbExtraAttrs(p);
      let sh = r1;
      const bChips = lbChips(p.strengths);
      if (bChips) sh += (sh ? '<div class="lb-stat-break"></div>' : '') + bChips;
      statsRow.style.display = 'flex';
      lbxSet(statsRow, sh);
    } else if (isKabaddi) {
      let r1 = '';
      if (p.kabaddi_role || p.role) r1 += lbStat('Role', p.kabaddi_role || p.role);
      if (p.previous_club || p.current_team) r1 += lbStat('Club', p.previous_club || p.current_team);
      r1 += lbExtraAttrs(p);
      if (r1) {
        statsRow.style.display = 'flex';
        lbxSet(statsRow, r1);
      } else {
        statsRow.style.display = 'none';
      }
    } else if (p.batting_style || p.bowling_style || lbExtraAttrs(p)) {
      statsRow.style.display = 'flex';
      lbxSet(statsRow, '<div class="lb-stat-chip"><div class="lb-stat-lbl">Batting</div>' +
        '<div class="lb-stat-val">' + lbEsc(p.batting_style || '—') + '</div></div>' +
        '<div class="lb-stat-chip"><div class="lb-stat-lbl">Bowling</div>' +
        '<div class="lb-stat-val">' + lbEsc(p.bowling_style || '—') + '</div></div>' +
        lbExtraAttrs(p));
    } else {
      statsRow.style.display = 'none';
    }

    // Base price
    if (p.base_price) {
      document.getElementById('lb-base-row').style.display = '';
      var _bv = document.getElementById('lb-base-val'), _bt = fmtPts(p.base_price); if (_bv.textContent !== _bt) _bv.textContent = _bt;
    } else {
      document.getElementById('lb-base-row').style.display = 'none';
    }
  }

  // ── Render Status Card ─────────────────────────────────────────
  function lbxWaitHtml(inner, live) {
    return '<div class="lbx-wait' + (live ? ' lbx-wait-live' : '') + '"><div class="lbx-spin"></div><div>' + inner + '</div></div>';
  }
  function renderStatus(currentPlayer, soldInfo, waitPhase) {
    rememberWaitPhase(waitPhase);
    const card = document.getElementById('lb-status-card');
    let html, lead = null, leadSold = false;
    const idleHtml = lbxWaitHtml(idleLineHtml(idleHeadline(_lbWaitPhase), idleShowDots(_lbWaitPhase)), false);

    if (!currentPlayer) {
      html = idleHtml;
    } else if (currentPlayer.state === 'sold' && soldInfo) {
      const f = fmtParts(soldInfo.amount);
      html = '<div class="lbx-bid is-sold">' +
        '<div class="lbx-bid-top"><span>Sold For \u00b7 ' + lbEsc(f.sym) + '</span><em>Hammer Down</em></div>' +
        '<div class="lbx-bid-amt">' + f.num + '</div>' +
        '<div class="lbx-lead"><div><small>Sold to</small><strong>' + lbEsc(soldInfo.team_name || '') + '</strong></div></div>' +
        '</div>';
      lead = soldInfo.team_name; leadSold = true;
    } else if (currentPlayer.state === 'auction') {
      const bid = (currentPlayer.current_bid > 0) ? currentPlayer.current_bid : 0;
      const bidTeam = currentPlayer.current_bid_team || null;
      if (bid > 0) {
        const f = fmtParts(bid);
        const logo = bidTeam && bidTeam.logo_url
          ? '<img src="' + lbEsc(bidTeam.logo_url) + '" alt="" onerror="this.outerHTML=\'<span class=lbx-lead-ph>\\ud83d\\udee1</span>\'">'
          : '<span class="lbx-lead-ph">\ud83d\udee1</span>';
        html = '<div class="lbx-bid is-live">' +
          '<div class="lbx-bid-top"><span>Current Bid \u00b7 ' + lbEsc(f.sym) + '</span><em>Bidding Open</em></div>' +
          '<div class="lbx-bid-amt">' + f.num + '</div>' +
          '<div class="lbx-lead">' + logo + '<div><small>Highest bidder</small><strong>' +
          lbEsc(bidTeam ? (bidTeam.name || 'Leading team') : 'Leading bid') + '</strong></div></div>' +
          '</div>';
        lead = bidTeam ? bidTeam.name : null;
      } else {
        html = lbxWaitHtml('<span class="lb-idle-copy">Accepting bids from teams</span>' + idleDotsHtml(), true);
      }
    } else if (currentPlayer.state === 'unsold') {
      html = '<div class="lbx-bid is-unsold">' +
        '<div class="lbx-bid-top"><span>Auction Result</span><em>No Bid</em></div>' +
        '<div class="lbx-bid-amt is-text">UNSOLD</div>' +
        '<div class="lbx-lead"><div><small>Result</small><strong>No team picked this player</strong></div></div>' +
        '</div>';
    } else {
      html = idleHtml;
    }
    if (card._lbxHtml !== html) {
      card._lbxHtml = html;
      card.innerHTML = html;
      lbxFitAmount();
    }
    lbxMarkLeadTeam(lead, leadSold);
  }

  // ── Render History ─────────────────────────────────────────────
  function formatHistoryMsg(msg) {
    if (!msg) return '';
    return String(msg).toUpperCase()
      .replace(/\bSOLD TO\b/g, 'sold to')
      .replace(/\bFOR\b/g, 'for');
  }

  function renderHistory(history) {
    const list = document.getElementById('lb-history-list');
    var fp = JSON.stringify(history || []);
    if (fp === _fpHistory) return;
    _fpHistory = fp;
    lbxBuildTicker(history);
    if (!history || !history.length) {
      list.innerHTML = '<div class="lbx-empty">No transactions yet</div>';
      return;
    }
    list.innerHTML = history.map(h => {
      const raw = String(h.message || '');
      const unsold = /unsold/i.test(raw);
      const msg = formatHistoryMsg(raw);
      let main = msg, amt = '';
      const mAmt = /^(.*)\sfor\s(\S.*)$/.exec(msg);
      if (mAmt && !unsold) { main = mAmt[1]; amt = mAmt[2]; }
      const mTeam = /^(.*?)\s+sold to\s+(.*)$/.exec(main);
      const msgHtml = mTeam
        ? lbEsc(mTeam[1]) + ' <small>\u2014 sold to ' + lbEsc(mTeam[2]) + '</small>'
        : lbEsc(main);
      const avatar = h.team_logo_url
        ? '<img src="' + lbEsc(h.team_logo_url) + '" alt="" onerror="this.parentElement.textContent=\'\\ud83c\\udfc5\'">'
        : '\ud83c\udfc5';
      return '<div class="lbx-fi' + (unsold ? ' un' : '') + '">' +
        '<div class="lbx-fi-av">' + avatar + '</div>' +
        '<div class="lbx-fi-msg">' + msgHtml + '</div>' +
        (amt ? '<div class="lbx-fi-amt">' + lbEsc(amt) + '</div>' : '') +
        '<div class="lbx-fi-time">' + lbEsc(h.timestamp || '') + '</div>' +
        '</div>';
    }).join('');
  }

  // ── Render MVP / Top Buys ──────────────────────────────────────
  function renderTopPlayers(topPlayers) {
    const list = document.getElementById('lb-mvp-list');
    var fp = JSON.stringify(topPlayers || []);
    if (fp === _fpMvp) return;
    _fpMvp = fp;
    if (!topPlayers || !topPlayers.length) {
      list.innerHTML = '<div class="lbx-empty">No sold players yet</div>';
      return;
    }
    const medals = ['\ud83d\udc51', '\ud83e\udd48', '\ud83e\udd49'];
    list.innerHTML = topPlayers.map((p, idx) => {
      const av = p.player_photo_url
        ? '<img src="' + lbEsc(p.player_photo_url) + '" alt="" onerror="this.style.display=\'none\'">'
        : '\ud83d\udc64';
      const tm = p.team_name
        ? '<div class="lbx-tp-tm">' + (p.team_logo_url ? '<img src="' + lbEsc(p.team_logo_url) + '" alt="">' : '') +
          '<span>' + lbEsc(p.team_name) + '</span></div>'
        : '';
      return '<div class="lbx-tp' + (idx === 0 ? ' r1' : '') + '">' +
        '<div class="lbx-tp-rk">' + (p.rank || (idx + 1)) + '</div>' +
        '<div class="lbx-tp-av">' + av + '</div>' +
        '<div class="lbx-tp-info">' +
          '<div class="lbx-tp-nm">' + (medals[idx] ? medals[idx] + ' ' : '') + lbEsc(p.player_name || '—') + '</div>' +
          '<div class="lbx-tp-rl">' + lbEsc(p.role || '') + '</div>' +
          '<div class="lbx-tp-pt">' + fmtParts(p.points).num + '</div>' +
          tm +
        '</div></div>';
    }).join('');
  }

  // ── Render Teams Strip ─────────────────────────────────────────
  function renderTeams(teams) {
    const card = document.getElementById('lb-teams-card');
    const grid = document.getElementById('lb-teams-grid');
    var fp = JSON.stringify(teams || []);
    if (fp === _fpTeams) return;
    _fpTeams = fp;
    if (!teams || !teams.length) { card.style.display = 'none'; return; }
    card.style.display = '';
    _teamsData = teams;
    card.setAttribute('data-rows', teams.length > 7 ? String(Math.min(3, Math.ceil(teams.length / 7))) : '1');
    grid.innerHTML = teams.map(function(t, idx) {
      const logoHtml = t.logo_url
        ? '<img src="' + lbEsc(t.logo_url) + '" alt="" onerror="this.parentElement.textContent=\'\\ud83d\\udee1\'">'
        : '\ud83d\udee1';
      return '<div class="lbx-team" data-team-idx="' + idx + '" data-name="' + lbEsc(String(t.name || '').trim().toLowerCase()) +
        '" tabindex="0" role="button" aria-label="View ' + lbEsc(t.name) + ' squad">' +
        '<div class="lbx-team-logo">' + logoHtml + '</div>' +
        '<div class="lbx-team-txt">' +
          '<div class="lbx-team-name">' + lbEsc(t.name) + '</div>' +
          '<div class="lbx-team-pts">' + fmtPts(t.remaining_points) + ' left</div>' +
        '</div></div>';
    }).join('');

    // Attach interaction events to each chip
    const isTouch = window.matchMedia('(pointer: coarse)').matches;
    Array.from(grid.querySelectorAll('.lbx-team')).forEach(function(chip) {
      var idx = parseInt(chip.dataset.teamIdx, 10);
      if (!isTouch) {
        // Desktop: hover shows floating popup
        chip.addEventListener('mouseenter', function() { showTeamPopup(idx, chip); });
        chip.addEventListener('mouseleave', hideTeamPopup);
        chip.addEventListener('focus',      function() { showTeamPopup(idx, chip); });
        chip.addEventListener('blur',       hideTeamPopup);
      }
      // Click / tap always opens the modal (works on both touch and desktop)
      chip.addEventListener('click', function() { openTeamModal(idx); });
    });
    if (_lbxLead) lbxMarkLeadTeam(_lbxLead.name, _lbxLead.sold);
  }

  // ── Build squad table rows (used in popup) ─────────────────────
  function buildSquadPopupHtml(players) {
    if (!players || !players.length) {
      return '<div class="lb-tp-empty">No players signed yet</div>';
    }
    const rows = players.map(function(p) {
      const photoHtml = p.photo_url
        ? `<span class="lb-tp-photo"><img src="${p.photo_url}" alt="" onerror="this.style.display='none';this.parentElement.innerHTML='<span class=lb-tp-ph>&#128100;</span>'"/></span>`
        : '<span class="lb-tp-photo"><span class="lb-tp-ph">&#128100;</span></span>';
      const meta = playerRoleMetaHtml(p);
      return `<tr>
        <td>${photoHtml}</td>
        <td>
          <div class="lb-tp-pname" style="font-weight:700;line-height:1.25;">${lbEsc(p.name) || '&#8212;'}</div>
          ${meta ? `<div class="lb-tm-rrole" style="margin-top:2px;">${meta}</div>` : ''}
        </td>
        <td class="lb-tp-pts">${fmtPts(p.points)}</td>
      </tr>`;
    }).join('');
    return `<table class="lb-tp-table">
      <thead><tr><th colspan="2">Player</th><th>Points</th></tr></thead>
      <tbody>${rows}</tbody>
    </table>`;
  }

  // ── Show / hide floating popup (desktop hover) ─────────────────
  function showTeamPopup(teamIdx, chipEl) {
    var team = _teamsData[teamIdx];
    if (!team) return;
    var popup   = document.getElementById('lb-team-floating-popup');
    var titleEl = document.getElementById('lb-tp-title');
    var contentEl = document.getElementById('lb-tp-content');
    titleEl.textContent = team.name + ' \u2014 Squad (' + (team.players ? team.players.length : 0) + ')';
    contentEl.innerHTML = buildSquadPopupHtml(team.players);
    popup.style.display = 'block';
    // Position above the chip, centred
    var rect = chipEl.getBoundingClientRect();
    var popW = popup.offsetWidth || 280;
    var left = rect.left + rect.width / 2 - popW / 2;
    var top  = rect.top + window.scrollY - popup.offsetHeight - 10;
    left = Math.max(8, Math.min(left, window.innerWidth - popW - 8));
    if (top < window.scrollY + 8) { top = rect.bottom + window.scrollY + 10; }
    popup.style.left = left + 'px';
    popup.style.top  = top  + 'px';
  }

  function hideTeamPopup() {
    var popup = document.getElementById('lb-team-floating-popup');
    if (popup) popup.style.display = 'none';
  }

  // ── Open team modal (mobile / click) ──────────────────────────
  function openTeamModal(teamIdx) {
    var team = _teamsData[teamIdx];
    if (!team) return;
    hideTeamPopup();
    var logoEl = document.getElementById('lb-tm-hlogo');
    logoEl.innerHTML = team.logo_url
      ? `<img src="${team.logo_url}" alt="" onerror="this.parentElement.innerHTML='&#128737;'">`
      : '&#128737;';
    document.getElementById('lb-tm-hname').textContent = team.name;
    document.getElementById('lb-tm-hpts').textContent  = fmtPts(team.remaining_points) + ' remaining';
    var body = document.getElementById('lb-tm-body');
    if (!team.players || !team.players.length) {
      body.innerHTML = '<div class="lb-tm-empty">No players signed yet</div>';
    } else {
      body.innerHTML = team.players.map(function(p) {
        const photoHtml = p.photo_url
          ? `<img src="${p.photo_url}" alt="" onerror="this.style.display='none';this.parentElement.innerHTML='<span class=lb-tm-rph>&#128100;</span>'">`
          : '<span class="lb-tm-rph">&#128100;</span>';
        const meta = playerRoleMetaHtml(p);
        return `<div class="lb-tm-row">
          <div class="lb-tm-rphoto">${photoHtml}</div>
          <div class="lb-tm-rinfo">
            <div class="lb-tm-rname">${lbEsc(p.name) || '&#8212;'}</div>
            ${meta ? `<div class="lb-tm-rrole">${meta}</div>` : ''}
          </div>
          <div class="lb-tm-rpts">${fmtPts(p.points)}</div>
        </div>`;
      }).join('');
    }
    document.getElementById('lb-team-modal-overlay').classList.add('open');
  }

  // ── Modal close handlers (event delegation — elements render after script) ──
  document.addEventListener('click', function(e) {
    if (e.target.id === 'lb-tm-hclose') {
      document.getElementById('lb-team-modal-overlay').classList.remove('open');
    } else if (e.target.id === 'lb-team-modal-overlay') {
      e.target.classList.remove('open');
    }
  });

  // ── Render Tournament Stats ────────────────────────────────────
  function setStat(id, val) {
    var el = document.getElementById(id);
    if (el) el.textContent = (val == null ? 0 : val);
  }
  function renderStats(stats) {
    var card = document.getElementById('lb-stats-card');
    if (!card) return;
    if (!stats || stats.total == null) { card.style.display = 'none'; return; }
    card.style.display = '';
    setStat('lb-stat-inauction', stats.in_auction);
    setStat('lb-stat-sold',      stats.sold);
    setStat('lb-stat-unsold',    stats.unsold);
    setStat('lb-stat-total',     stats.total);
    var total = Number(stats.total) || 0;
    var sold = Number(stats.sold) || 0, unsold = Number(stats.unsold) || 0, live = Number(stats.in_auction) || 0;
    var pct = function(n) { return total ? Math.min(100, (n / total) * 100).toFixed(2) + '%' : '0'; };
    var ok = document.getElementById('lbx-prog-ok'), no = document.getElementById('lbx-prog-no'), lv = document.getElementById('lbx-prog-live');
    if (ok) ok.style.width = pct(sold);
    if (no) no.style.width = pct(unsold);
    if (lv) lv.style.width = pct(live);
    var tx = document.getElementById('lbx-prog-txt');
    if (tx) tx.textContent = (sold + unsold) + ' / ' + total + ' players';
    var of = document.getElementById('lb-sl-of');
    if (of) of.textContent = total ? 'OF ' + total : '';
  }

  // ── Polling ────────────────────────────────────────────────────
  function applyLiveBoardData(data) {
        if (!data) return;
        // Apply theme + sport
        if (data.theme) {
          document.documentElement.setAttribute('data-theme', data.theme);
        }
        if (data.tournament_type || (data.tournament && data.tournament.tournament_type)) {
          _sport = (data.tournament_type || data.tournament.tournament_type || 'cricket').toLowerCase();
          document.documentElement.setAttribute('data-sport', _sport);
        }

        const p = data.current_player;
        if (window.acLiveBidTick) {
          window.acLiveBidTick.maybePlay(
            !!(data.live_bid_sound || (data.tournament && data.tournament.live_bid_sound)),
            p
          );
        }
        if (window.acSoldCoin) {
          var soldAmt = (data.sold_info && data.sold_info.amount) || (p && p.sold_points) || 0;
          window.acSoldCoin.maybePlay(
            !!(data.sold_coin_sound || (data.tournament && data.tournament.sold_coin_sound)),
            p,
            soldAmt
          );
        }
        const newId    = p ? p.id    : null;
        const newState = p ? p.state : null;
        const newMysteryRevealed = p ? !!p.mystery_revealed : null;

        const playerChanged = (newId !== lastPlayerId) || (newState !== lastState)
          || (newMysteryRevealed !== lastMysteryRevealed);
        const playerSwitched = (newId !== lastPlayerId);
        const waitPhase = data.wait_phase || {};
        rememberWaitPhase(waitPhase);
        if (playerSwitched) {
          renderPlayer(p, data.sold_info, waitPhase);
          renderStatus(p, data.sold_info, waitPhase);
        } else if (playerChanged && (lastPlayerId !== null || newId !== null)) {
          const panel = document.getElementById('lb-player-panel');
          panel.style.transition = 'opacity 0.3s';
          panel.style.opacity = '0';
          setTimeout(function() {
            renderPlayer(p, data.sold_info, waitPhase);
            renderStatus(p, data.sold_info, waitPhase);
            panel.style.opacity = '1';
          }, 300);
        } else {
          renderPlayer(p, data.sold_info, waitPhase);
          renderStatus(p, data.sold_info, waitPhase);
        }

        lastPlayerId = newId;
        lastState    = newState;
        lastMysteryRevealed = newMysteryRevealed;

        renderHistory(data.recent_history);
        renderTopPlayers(data.top_players || []);
        renderTeams(data.teams);
        renderStats(data.stats);
        handleThankYou(data.wait_phase || {}, data.tournament || {}, p);
        handleBreakTime(!!data.break_time, data.tournament || {});
        updateAds(data.advertisers || []);
  }

  function poll() {
    fetch(document.documentElement.dataset.liveDataUrl, { cache: 'no-store' })
      .then(r => r.json())
      .then(data => { applyLiveBoardData(data); })
      .catch(function() {});
  }

  // Initial load + periodic refresh with Page Visibility pause
  var _pollTimer = null;
  function startPolling() { if (!_pollTimer) _pollTimer = setInterval(poll, 2000); }
  function stopPolling()  { if (_pollTimer) { clearInterval(_pollTimer); _pollTimer = null; } }
  document.addEventListener('visibilitychange', function() {
    if (document.hidden) { stopPolling(); }
    else { poll(); startPolling(); }
  });
  window.addEventListener('beforeunload', function() { stopPolling(); clearInterval(_clockTimer); });
  window.__acApplyLiveBoard = applyLiveBoardData;
  var _sseCtl = null;
  if (window.AuctionChampSSE && window.AuctionChampSSE.enabled(document.documentElement)) {
    _sseCtl = window.AuctionChampSSE.bind({
      url: document.documentElement.dataset.sseUrl,
      apply: applyLiveBoardData,
      startPoll: function () { poll(); startPolling(); },
      stopPoll: stopPolling,
      onStampExpiry: function () { poll(); },
    });
  } else {
    poll();
    startPolling();
  }
  window._auctionLbPoll = poll;
})();

// Poll every 15 seconds; reload the page when the board goes live
(function () {
  var dataUrl = window.location.href.replace('/auction/live-board', '/auction/live-board/data');
  function check() {
    fetch(dataUrl)
      .then(function(r){ return r.json(); })
      .then(function(d){
        if (d.live_board_active !== false) {
          window.location.reload();
        }
      })
      .catch(function(){});
  }
  setInterval(check, 15000);
})();
